#!/usr/bin/env node
// Validates demo/timeline.json — the file Remotion renders from.
//
// timeline.json is generated by reconcile.mjs, so this validator exists to catch two
// things: a hand-edit that broke an invariant, and a reconcile run against media that
// has since changed. Every media reference is checked on disk and re-measured.

import { accessSync, constants, existsSync, readFileSync, statSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { execFileSync } from 'node:child_process';

const file = process.argv[2];
if (!file) {
  console.error('usage: validate-timeline.mjs <timeline.json> [--project DIR]');
  process.exit(1);
}

const publicDir = dirname(resolve(file)); // demo/ — Remotion's --public-dir
const errors = [];
const warnings = [];

let tl;
try {
  tl = JSON.parse(readFileSync(file, 'utf8'));
} catch (err) {
  console.error(`demo-video: timeline.json is not valid JSON — ${err.message}`);
  process.exit(1);
}

const fps = Number(tl.fps || 0);
if (!fps) errors.push('fps is required.');
if (!tl.width || !tl.height) errors.push('width and height are required.');

const hasFfprobe = (process.env.PATH || '').split(':').some((dir) => {
  try {
    accessSync(join(dir, 'ffprobe'), constants.X_OK);
    return true;
  } catch {
    return false;
  }
});

const probeDuration = (abs) => {
  if (!hasFfprobe) return null;
  try {
    const out = execFileSync(
      'ffprobe',
      ['-v', 'error', '-show_entries', 'format=duration', '-of', 'csv=p=0', abs],
      { encoding: 'utf8' }
    );
    const n = Number(out.trim());
    return Number.isFinite(n) ? n : null;
  } catch {
    return null;
  }
};

const checkMedia = (rel, declared, at) => {
  if (!rel) return;
  const abs = join(publicDir, rel);
  if (!existsSync(abs)) {
    errors.push(`${at}: "${rel}" does not exist under ${publicDir}. Remotion resolves it via staticFile().`);
    return;
  }
  if (statSync(abs).size < 2048) {
    errors.push(`${at}: "${rel}" is ${statSync(abs).size} bytes — an empty or failed asset.`);
    return;
  }
  const actual = probeDuration(abs);
  if (actual !== null && declared) {
    if (Math.abs(actual - declared) > 0.2) {
      errors.push(
        `${at}: "${rel}" measures ${actual.toFixed(3)}s but the timeline declares ${declared}s. ` +
          'The media changed since reconcile — re-run reconcile.mjs so timings are rebuilt.'
      );
    }
  }
};

const sections = Array.isArray(tl.sections) ? tl.sections : [];
if (!sections.length) errors.push('No sections.');

let prevEnd = 0;
sections.forEach((s, i) => {
  const at = `sections[${i}]${s?.id ? ` (${s.id})` : ''}`;
  if (!s.id) errors.push(`${at}: id is required.`);
  if (!Number.isInteger(s.startFrame) || s.startFrame < 0) errors.push(`${at}: startFrame must be a non-negative integer.`);
  if (!Number.isInteger(s.durationInFrames) || s.durationInFrames < 1) {
    errors.push(`${at}: durationInFrames must be a positive integer.`);
  }

  if (i > 0 && Number.isInteger(s.startFrame)) {
    if (s.startFrame > prevEnd) {
      errors.push(
        `${at}: starts at frame ${s.startFrame} but the previous section ended at ${prevEnd} — ` +
          `a ${((s.startFrame - prevEnd) / fps).toFixed(2)}s black gap.`
      );
    }
    const overlap = prevEnd - s.startFrame;
    if (overlap > fps * 1.5) {
      warnings.push(`${at}: overlaps the previous section by ${(overlap / fps).toFixed(2)}s — long for a demo transition.`);
    }
  }
  prevEnd = (s.startFrame ?? 0) + (s.durationInFrames ?? 0);

  if (s.video) {
    checkMedia(s.video.src, s.video.measuredSeconds, `${at}.video`);
    const rate = s.video.playbackRate ?? 1;
    if (rate < 0.5 || rate > 2) errors.push(`${at}.video.playbackRate ${rate} is outside 0.5-2.`);
    const warp = s.video.warpRatio ?? rate;
    if (Math.abs(1 - warp) > 0.155) {
      errors.push(
        `${at}.video: time warp ${((warp - 1) * 100).toFixed(0)}% exceeds the 15% limit — ` +
          'the motion will look wrong. Rewrite the narration for this section or re-capture it.'
      );
    }
    const hold = s.video.holdLastFrameFrames ?? 0;
    if (hold > s.durationInFrames * 0.4) {
      warnings.push(
        `${at}.video: ${(hold / fps).toFixed(1)}s of this ${(s.durationInFrames / fps).toFixed(1)}s section is a frozen ` +
          'last frame. Re-capture with longer dwell, or shorten the narration.'
      );
    }
    if (s.video.trimBefore !== undefined && !Number.isInteger(s.video.trimBefore)) {
      errors.push(`${at}.video.trimBefore must be an integer number of FRAMES (Remotion prop), not seconds.`);
    }
    if (s.video.trimAfter !== undefined && !Number.isInteger(s.video.trimAfter)) {
      errors.push(`${at}.video.trimAfter must be an integer number of FRAMES (Remotion prop), not seconds.`);
    }
  } else if (['web', 'electron'].includes(s.surface)) {
    errors.push(`${at}: surface "${s.surface}" has no video. The clip is missing — capture it before rendering.`);
  }

  if (s.audio) {
    checkMedia(s.audio.src, s.audio.measuredSeconds, `${at}.audio`);
    const audioEnd = (s.audio.delayFrames ?? 0) + Math.round((s.audio.measuredSeconds ?? 0) * fps);
    if (audioEnd > s.durationInFrames + 2) {
      errors.push(
        `${at}.audio: narration runs ${((audioEnd - s.durationInFrames) / fps).toFixed(2)}s past the end of the ` +
          'section and will be cut off mid-sentence.'
      );
    }
  }

  (s.captions ?? []).forEach((c, j) => {
    if (c.endFrame <= c.startFrame) errors.push(`${at}.captions[${j}]: endFrame must be after startFrame.`);
    if (c.endFrame > s.durationInFrames + 2) warnings.push(`${at}.captions[${j}]: extends past the section end.`);
  });
});

if (tl.music?.src) checkMedia(tl.music.src, null, 'music');

if (tl.durationInFrames !== prevEnd) {
  errors.push(
    `durationInFrames is ${tl.durationInFrames} but the last section ends at frame ${prevEnd}. ` +
      (tl.durationInFrames > prevEnd ? 'The video would end on black.' : 'The final section would be cut off.')
  );
}

const actualSeconds = prevEnd / (fps || 30);
const targetSeconds = Number(tl.report?.targetSeconds || 0);
if (targetSeconds) {
  const drift = (actualSeconds - targetSeconds) / targetSeconds;
  if (Math.abs(drift) > 0.15) {
    warnings.push(
      `Final length ${actualSeconds.toFixed(1)}s vs target ${targetSeconds}s (${(drift * 100).toFixed(0)}% off).`
    );
  }
}

if (errors.length) {
  console.error(
    [
      `demo-video: timeline.json has ${errors.length} error(s) — rendering now would produce a broken video.`,
      ...errors.map((e) => `  ERROR  ${e}`),
      ...warnings.map((w) => `  warn   ${w}`),
    ].join('\n')
  );
  process.exit(1);
}

console.log(
  [
    `demo-video: timeline valid — ${sections.length} sections, ${actualSeconds.toFixed(1)}s ` +
      `(${prevEnd} frames @ ${fps}fps, ${tl.width}x${tl.height}).`,
    ...warnings.map((w) => `  warn   ${w}`),
  ].join('\n')
);
